import{_ as s,H as e,f as n,i as p}from"./chunks/framework.BH2BK_3i.js";const g=JSON.parse('{"title":"10｜基础组件（上）：后端业务基础设施","description":"","frontmatter":{},"headers":[{"level":2,"title":"新的协作模式：先问再做","slug":"新的协作模式-先问再做","link":"#新的协作模式-先问再做","children":[]},{"level":2,"title":"让 Claude Code 梳理基础组件清单","slug":"让-claude-code-梳理基础组件清单","link":"#让-claude-code-梳理基础组件清单","children":[]},{"level":2,"title":"第一档：让业务代码能跑起来","slug":"第一档-让业务代码能跑起来","link":"#第一档-让业务代码能跑起来","children":[]},{"level":2,"title":"第二档：业务开发的基础能力","slug":"第二档-业务开发的基础能力","link":"#第二档-业务开发的基础能力","children":[]},{"level":2,"title":"第三档：健壮性补齐","slug":"第三档-健壮性补齐","link":"#第三档-健壮性补齐","children":[]},{"level":2,"title":"最终验收","slug":"最终验收","link":"#最终验收","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"ClaudeCode企业级全链路开发实战/10｜基础组件（上）：后端业务基础设施.md","filePath":"ClaudeCode企业级全链路开发实战/10｜基础组件（上）：后端业务基础设施.md","lastUpdated":1779815375000}'),t={name:"ClaudeCode企业级全链路开发实战/10｜基础组件（上）：后端业务基础设施.md"};function l(i,a,o,c,r,d){return e(),n("div",null,[...a[0]||(a[0]=[p(`<h1 id="_10-基础组件-上-后端业务基础设施" tabindex="-1">10｜基础组件（上）：后端业务基础设施 <a class="header-anchor" href="#_10-基础组件-上-后端业务基础设施" aria-label="Permalink to &quot;10｜基础组件（上）：后端业务基础设施&quot;">​</a></h1><p>你好，我是Robert。</p><p>工程初始化完成了，Hify前后端都能跑， <code>make start</code> 一键启动。但现在还不能直接写业务，“空项目”还缺一层东西： <strong>基础组件</strong>。</p><p>08讲搭hify-common的时候，我们做了配置层面的基础，MyBatis-Plus的分页插件和自动填充、Redis的RedisTemplate 和序列化配置。但业务封装层还没做，比如：</p><ol><li>BaseEntity基类怎么定</li><li>分页查询怎么从前端参数转成PageResult</li><li>接口入参怎么校验</li><li>调外部LLM API的HTTP客户端怎么封装</li><li>线程池怎么隔离</li><li>熔断怎么配</li></ol><p>这些是所有业务模块都会用到的底层能力，不先搭好，后面每个模块都要重复处理一遍。但问题来了： <strong>具体需要准备哪些基础组件？你可能有经验能列出一部分，但难免有遗漏</strong>。这一讲引入一个新的协作模式来解决这个问题。</p><h2 id="新的协作模式-先问再做" tabindex="-1">新的协作模式：先问再做 <a class="header-anchor" href="#新的协作模式-先问再做" aria-label="Permalink to &quot;新的协作模式：先问再做&quot;">​</a></h2><p>回顾前面几讲，我们和Claude Code的协作基本都是一个模式： <strong>你想清楚了，让它做</strong>。“按照规范实现这个接口”，“帮我生成Maven骨架”……你知道要做什么，它负责执行。</p><p>但现在的情况不一样，“业务开发前需要准备哪些基础组件”这个问题，你有大致想法，但不确定有没有遗漏、先后顺序对不对。</p><p>这时候换一种模式： <strong>先让 Claude Code 帮你想，再让它做</strong>。不是让它替你做决策，而是 <strong>把它当成一个资深架构师来咨询</strong>，你问“这一步应该考虑什么”，它帮你梳理全景，你判断哪些要做、哪些不做，然后再进入执行。</p><p>我把这两种模式叫 <strong>执行模式</strong> 和 <strong>咨询模式</strong>：</p><ul><li><p>执行模式：你想清楚了 → 给指令 → Claude Code做 → 你验收。适合你对任务很清楚的时候。</p></li><li><p>咨询模式：你知道大方向但不确定细节 → 先问Claude Code → 它帮你梳理 → 你判断取舍 → 再给指令执行。适合不确定性高的时候。</p></li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/4bb67268335f9854036da39c1b7dfd52.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/4bb67268335f9854036da39c1b7dfd52.jpg" alt=""></a></p><p>这个方法论后面会反复用到。每次进入新阶段（新模块、测试、部署），都可以先用咨询模式问一句“这个阶段我应该考虑什么”，确保不遗漏。</p><h2 id="让-claude-code-梳理基础组件清单" tabindex="-1">让 Claude Code 梳理基础组件清单 <a class="header-anchor" href="#让-claude-code-梳理基础组件清单" aria-label="Permalink to &quot;让 Claude Code 梳理基础组件清单&quot;">​</a></h2><p>直接用。我问Claude Code：</p><blockquote><p>Hify项目工程骨架已经搭好（Maven多模块、hify-common的Result / 异常处理 / MyBatis-Plus配置 / Redis配置、前端Vue工程）。现在要开始做业务功能了。在写业务代码之前，还需要准备哪些基础组件？从数据库层、接口层、外部调用、缓存、可观测性几个角度帮我梳理，每个组件说明它解决什么问题。</p></blockquote><p>它给了一份很详细的清单。我就不放细节了，就放一个总结：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/2144ab642ebd1e1df536f2b146499eyy.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/2144ab642ebd1e1df536f2b146499eyy.png" alt=""></a></p><p>有些是我预期到的（线程池、熔断），但有几个是我自己列清单时会漏掉的。我按优先级做了分档，不是所有东西都要现在做，有些不做业务就跑不起来，有些可以写业务时同步补。</p><p><strong>第一档：必须先做，否则业务代码跑不起来</strong></p><ol><li><p>数据库初始化脚本（schema.sql）。这是我差点忽略的，现在还没有建表DDL。Spring Boot启动时需要库和表已存在，否则Mapper跑不起来。需要创建所有业务表的DDL文件。</p></li><li><p>@MapperScan扫描路径。目前启动类的扫描路径只覆盖了 <code>com.hify.app</code>，但业务Mapper在各子模块里（ <code>com.hify.provider.mapper</code> 等），Bean注册不上。不改这个，所有Mapper注入都会报错。</p></li><li><p>llmExecutor / asyncExecutor线程池。CLAUDE.md要求LLM调用必须用 <code>@Qualifier(&quot;llmExecutor&quot;)</code>，Chat模块注入时这个Bean必须存在。</p></li></ol><p><strong>第二档：做业务时同步补，第一个列表接口之前搞定</strong></p><ol><li><p>BaseEntity（公共字段封装）。每个实体都有id、created_at、updated_at、deleted，不封装就每个实体重复写。</p></li><li><p>统一分页参数封装。几乎每个列表接口都要分页，把前端参数转成MyBatis-Plus的Page对象，封装一次全部复用。</p></li><li><p>入参校验（@Valid）。每个创建/更新接口都需要参数校验，和08讲的全局异常处理器串起来。</p></li><li><p>统一时间序列化。不配的话Jackson序列化LocalDateTime默认输出数组格式 <code>[2025,3,16,10,30,0]</code>，前端解析不了。</p></li><li><p>Spring Cache集成。CLAUDE.md规定 Provider / Agent 配置走Redis Cache-Aside，TTL 30min。现在只有裸RedisUtil，没有启用 <code>@EnableCaching</code> + <code>RedisCacheManager</code>， <code>@Cacheable</code> 注解用不了。</p></li></ol><p><strong>第三档：可以后补，不影响功能开发</strong></p><ol><li><p>HTTP客户端封装。调LLM API的基础，但Chat模块开发时再做也来得及。</p></li><li><p>Resilience4j熔断配置。04讲定了每个提供商独立熔断器，但Chat模块完成后补也不迟。</p></li><li><p>结构化日志配置。logback-spring.xml区分开发/生产环境，请求日志过滤器记录method、path、耗时。联调阶段前补上。</p></li></ol><p>Claude Code帮我发现了两个我自己会漏掉的： <strong>schema.sql 和 @MapperScan</strong>。不是什么高深的东西，但你在列基础组件清单时很容易忽略。脑子里想的都是BaseEntity、线程池这些有设计感的东西，反而忘了最基础的东西，比如表还没建、扫描路径不对。等到启动报错才发现，浪费的是排查时间。</p><p><strong>这就是咨询模式的核心价值，用它做遗漏检查。Claude Code 见过的项目比你多，它的建议不能直接照搬，但用来查漏补缺非常好。</strong></p><p>我的决定是：这一讲把三档全做了。 虽然第三档可以后补，但提前搭好，后面就不用回头。按依赖关系排序：先做第一档（跑起来），再做第二档（业务能写），最后补第三档（健壮性），DemoItem验收放在第二档做完之后。</p><h2 id="第一档-让业务代码能跑起来" tabindex="-1">第一档：让业务代码能跑起来 <a class="header-anchor" href="#第一档-让业务代码能跑起来" aria-label="Permalink to &quot;第一档：让业务代码能跑起来&quot;">​</a></h2><p><strong>1. 数据库初始化脚本</strong></p><p>Claude Code提示词是：</p><blockquote><p>按照CLAUDE.md的数据库规范和数据模型，生成所有业务表的建表DDL。放在hify-app/src/main/resources/db/schema.sql。表名小写下划线、主键id bigint自增、时间字段created_at/updated_at datetime、逻辑删除deleted tinyint默认 0、字符集utf8mb4。包含：provider、model_config、agent、agent_tool、mcp_server、chat_session、chat_message。</p></blockquote><p>效果是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/c806663abba47104b75719d4a23f1a08.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/c806663abba47104b75719d4a23f1a08.png" alt=""></a></p><p>这个就不展开说明了，大家可以自己琢磨一下细节。</p><p><strong>2. @MapperScan 扫描路径</strong></p><p>这个改动就一行代码，但不改所有Mapper都注入不了：</p><blockquote><p>在HifyApplication启动类上加 @MapperScan(“com.hify.**.mapper”)，扫描所有子模块的Mapper包。</p></blockquote><p>效果是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/7d642yy30d211a3fe8a37fd1ecf8137e.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/7d642yy30d211a3fe8a37fd1ecf8137e.png" alt=""></a></p><p><strong>3. 线程池配置</strong></p><p>场景：用户在对话（调LLM，卡了30秒），同时另一个用户打开管理页面看Agent配置。如果共用线程池，对话请求占满了所有线程，管理页面一直转圈。</p><blockquote><p>在hify-common中创建ThreadPoolConfig（com.hify.common.config）。定义两个线程池：llmExecutor（核心10，最大50，队列100，线程名前缀llm-，拒绝策略CallerRunsPolicy）用于LLM调用；asyncExecutor（核心5，最大20，队列200，线程名前缀async-）用于日志异步写入等非关键任务。用@Bean + @Qualifier注册。</p></blockquote><p>参数依据：目标20-50人同时在线，一半的人同时对话就是10-25个并发LLM调用，核心线程10够用，最大50留余量。一期先这样，后面根据监控调整。</p><p>线程名前缀很重要，后面看日志时， <code>llm-3</code> 立刻知道是LLM调用线程， <code>async-1</code> 是异步任务线程。不设前缀全是 <code>pool-1-thread-3</code>，排查时分不清。</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>package com.hify.common.config;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import org.springframework.beans.factory.annotation.Qualifier;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Bean;</span></span>
<span class="line"><span>import org.springframework.context.annotation.Configuration;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>import java.util.concurrent.Executor;</span></span>
<span class="line"><span>import java.util.concurrent.LinkedBlockingQueue;</span></span>
<span class="line"><span>import java.util.concurrent.ThreadPoolExecutor;</span></span>
<span class="line"><span>import java.util.concurrent.TimeUnit;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&amp;#64;Configuration</span></span>
<span class="line"><span>public class ThreadPoolConfig {</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &amp;#64;Bean</span></span>
<span class="line"><span>    &amp;#64;Qualifier(&quot;llmExecutor&quot;)</span></span>
<span class="line"><span>    public Executor llmExecutor() {</span></span>
<span class="line"><span>        return new ThreadPoolExecutor(</span></span>
<span class="line"><span>                10, 50,</span></span>
<span class="line"><span>                60L, TimeUnit.SECONDS,</span></span>
<span class="line"><span>                new LinkedBlockingQueue&amp;lt;&amp;gt;(100),</span></span>
<span class="line"><span>                new NamedThreadFactory(&quot;llm-&quot;),</span></span>
<span class="line"><span>                new ThreadPoolExecutor.CallerRunsPolicy()</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &amp;#64;Bean</span></span>
<span class="line"><span>    &amp;#64;Qualifier(&quot;asyncExecutor&quot;)</span></span>
<span class="line"><span>    public Executor asyncExecutor() {</span></span>
<span class="line"><span>        return new ThreadPoolExecutor(</span></span>
<span class="line"><span>                5, 20,</span></span>
<span class="line"><span>                60L, TimeUnit.SECONDS,</span></span>
<span class="line"><span>                new LinkedBlockingQueue&amp;lt;&amp;gt;(200),</span></span>
<span class="line"><span>                new NamedThreadFactory(&quot;async-&quot;),</span></span>
<span class="line"><span>                new ThreadPoolExecutor.AbortPolicy()</span></span>
<span class="line"><span>        );</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>到这里， <code>mvn spring-boot:run</code> 应该能正常启动、Mapper能注入、线程池Bean就绪。跑一下确认没有启动报错，再进入第二档。</p><h2 id="第二档-业务开发的基础能力" tabindex="-1">第二档：业务开发的基础能力 <a class="header-anchor" href="#第二档-业务开发的基础能力" aria-label="Permalink to &quot;第二档：业务开发的基础能力&quot;">​</a></h2><p>接下来，我就不展示每个指令的执行效果了，比较复杂的我会展开说明。</p><p><strong>1. BaseEntity</strong></p><p>每个数据库实体都有公共字段。不封装的话，每个Entity都要重复写id、created_at、updated_at、deleted和对应的注解。</p><blockquote><p>在hify-common中创建BaseEntity类。字段：id（Long，@TableId自增）、createdAt（LocalDateTime，插入时自动填充）、updatedAt（LocalDateTime，插入和更新时自动填充）、deleted（Integer，@TableLogic，默认0）。后面所有业务实体继承这个类。</p></blockquote><p><strong>2. 统一分页封装</strong></p><p>08 讲定义了分页的请求参数（page、pageSize）和响应格式（PageResult），也配好了分页插件，但还没有把它们串起来。</p><blockquote><p>在hify-common中创建PageHelper工具类。提供两个静态方法：toPage(page, pageSize)把前端参数转成MyBatis-Plus的Page对象（page从1开始，pageSize默认20最大100）；toPageResult(IPage)把查询结果转成我们的PageResult。</p></blockquote><p><strong>3. 入参校验</strong></p><p>每个创建和更新接口都需要校验入参。Spring Boot的 <code>@Valid</code> + JSR 303注解就够用，关键是和08讲的GlobalExceptionHandler配合好。它已经捕获了MethodArgumentNotValidException，会转成 <code>Result.fail(ErrorCode.PARAM_ERROR, 具体校验信息)</code>。</p><p><strong>4. 统一时间序列化</strong></p><blockquote><p>在hify-common中配置Jackson的全局时间序列化。LocalDateTime统一用ISO 8601格式（yyyy-MM-dd’T’HH:mm:ss），LocalDate用yyyy-MM-dd。配置JavaTimeModule，关掉WRITE_DATES_AS_TIMESTAMPS。</p></blockquote><p>一个配置类，十几行代码，但省掉后面无数前端时间解析的坑。</p><p><strong>5. Spring Cache 集成</strong></p><p>08讲配好了RedisTemplate和RedisUtil，但只是裸的get/set操作。业务层需要 <code>@Cacheable</code>、 <code>@CacheEvict</code> 这些声明式缓存。Provider配置读多写少，加个注解就自动缓存，不需要手动写if-else。</p><blockquote><p>在hify-common中启用Spring Cache。@EnableCaching，配置RedisCacheManager，默认TTL 30分钟，key前缀hify:。配置不同缓存名的TTL：provider-cache 30分钟、agent-cache 30分钟、session-cache 2小时。</p></blockquote><p>这样后面业务Service直接加 <code>@Cacheable(cacheNames = &quot;provider-cache&quot;)</code> 就行，缓存的读写、过期、序列化全自动处理。写入时加 <code>@CacheEvict</code> 失效缓存，标准的Cache-Aside模式。</p><p><strong>6. CRUD 标准流程验证</strong></p><p>第二档的所有组件搭好了，用一个DemoItem跑通完整CRUD，验证它们协同工作。</p><blockquote><p>实现一个最简单的CRUD演示。实体：DemoItem，只有name（String）和status（Integer）两个字段，继承BaseEntity。完整实现Controller → Service → ServiceImpl → Mapper → Entity → CreateReq/UpdateReq/Resp DTO。Controller使用RESTful路径 /api/v1/demo-items，返回统一Result，列表接口返回PageResult，创建和更新接口使用@Valid校验，Service层处理业务逻辑，Mapper继承BaseMapper。</p></blockquote><p>验收：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 入参校验生效吗？</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/demo-items</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;&quot;, &quot;status&quot;: 1}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 期望：Result.fail，提示 name 不能为空</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 正常创建</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> POST</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/demo-items</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -H</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;Content-Type: application/json&quot;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> \\</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  -d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{&quot;name&quot;: &quot;测试项&quot;, &quot;status&quot;: 1}&#39;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 期望：Result.ok(id)，数据库 created_at 自动填充</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 分页列表</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;http://localhost:8080/api/v1/demo-items?page=1&amp;pageSize=10&quot;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 期望：PageResult，时间字段是 ISO 8601 格式</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 逻辑删除</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -X</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> DELETE</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://localhost:8080/api/v1/demo-items/1</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># 期望：数据库 deleted=1，再查列表看不到了</span></span></code></pre></div><p>每一个请求验证一个基础组件：</p><ul><li>空name → 入参校验 + 全局异常处理器</li><li>创建成功 → BaseEntity自动填充</li><li>列表 → PageHelper + 分页插件</li><li>时间格式 → Jackson配置</li><li>逻辑删除 → MyBatis-Plus配置</li></ul><p>全部通过，说明第二档组件就绪。DemoItem留着不删，后面做Provider模块时，它是最好的参考模板。</p><h2 id="第三档-健壮性补齐" tabindex="-1">第三档：健壮性补齐 <a class="header-anchor" href="#第三档-健壮性补齐" aria-label="Permalink to &quot;第三档：健壮性补齐&quot;">​</a></h2><p>这些不做也能写业务，但从架构和实现的角度，最好提前搭好，后面不用回头。这也是培养咱们设计和实现系统的好习惯。</p><p><strong>1. HTTP 客户端封装</strong></p><p>Hify需要调用各种外部LLM API。先用咨询模式确认方案：</p><blockquote><p>帮我分析普通请求用RestTemplate、流式SSE请求用OkHttp EventSource这个方案，有没有问题？</p></blockquote><p>Claude Code确认方案合理，提醒了连接池要分开配、超时参数要区分。进入执行模式：</p><blockquote><p>在hify-common中创建LlmHttpClient 类（com.hify.common.http）。内部持有RestTemplate（连接超时5s，读超时60s）和 OkHttpClient（连接超时5s，读超时120s）。提供 post(url, headers, body) 方法返回String，提供stream(url, headers, body, callback) 方法通过回调逐行返回。所有请求记录日志（URL、耗时、状态码），异常统一转为LlmApiException（区分 TIMEOUT、AUTH_FAILED、RATE_LIMITED）。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/1e156345e0da78de4f79c40515a4f699.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/1e156345e0da78de4f79c40515a4f699.png" alt=""></a></p><p>上面是生成的局部代码。是不是很完整，比我写的都好。</p><p>这里有个点，为什么超时设这么长？ <strong>LLM API不是普通HTTP调用，GPT-4一次响应可能10-20秒，流式可能持续一两分钟。60秒和120秒是实际经验的平衡</strong>。这也是我们作为程序员的价值所在，我们会去理解需求，从宏观去思考超时时间是多久。因为AI不知道GPT-4一次响应可能10-20秒，这是物理世界的表现。</p><p><strong>2. Resilience4j 熔断与重试</strong></p><p>线程池解决了“一个LLM卡了不影响其他功能”的问题。熔断解决另一个问题：某个提供商整个挂了，系统还在不停发请求，每次等60秒超时——挂了就是挂了，等也白等。</p><blockquote><p>在hify-common中配置Resilience4j熔断器（com.hify.common.resilience）。application.yml配置：slidingWindowSize 10，failureRateThreshold 50%，waitDurationInOpenState 30s，permittedNumberOfCallsInHalfOpenState 3。创建CircuitBreakerService，按providerName获取或创建独立熔断器实例。重试逻辑：网络超时重试2次（间隔1s），限流退避重试（2s、4s），认证失败不重试。</p></blockquote><p>输出是：</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/ab67076f1ec3ccf3a2bf7dfda2a69a5c.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/ab67076f1ec3ccf3a2bf7dfda2a69a5c.png" alt=""></a></p><p>下图是熔断器状态流转图，你可以看看，理解一下代码的底层设计。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/31a5806f84824683673fdbe9b720982e.jpg" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/ClaudeCode%E4%BC%81%E4%B8%9A%E7%BA%A7%E5%85%A8%E9%93%BE%E8%B7%AF%E5%BC%80%E5%8F%91%E5%AE%9E%E6%88%98/images/966292/31a5806f84824683673fdbe9b720982e.jpg" alt=""></a></p><p>为什么每个Provider独立熔断器？OpenAI挂了不代表Claude也挂了。共用的话一家失败会把其他正常的也拦住。</p><p>重试按异常类型区分，认证失败重试一百次也不会成功，只有“暂时性”的失败才值得重试。</p><p><strong>3. 结构化日志与请求追踪</strong></p><blockquote><p>在hify-common中配置统一日志（com.hify.common.log）。logback-spring.xml区分环境：开发环境控制台彩色输出，生产环境JSON格式输出到文件（按天滚动，保留30天）。创建RequestLogInterceptor（HandlerInterceptor），记录每个请求的method、path、status、耗时，慢请求（&gt;1s）标WARN。请求进入时生成traceId放入MDC，请求结束时清理。日志格式： <code>%d{HH:mm:ss} [%thread] [%X{traceId}] %-5level %logger{20} - %msg%n</code>。</p></blockquote><p>输出是：</p><div class="language-plaintext vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">plaintext</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&amp;lt;?xml version=&quot;1.0&quot; encoding=&quot;UTF-8&quot;?&amp;gt;</span></span>
<span class="line"><span>&amp;lt;configuration&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &amp;lt;property name=&quot;LOG_DIR&quot; value=&quot;\${LOG_DIR:-logs}&quot;/&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;property name=&quot;APP_NAME&quot; value=&quot;hify&quot;/&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;property name=&quot;LOG_PATTERN&quot; value=&quot;%d{HH:mm:ss} [%thread] [%X{traceId}] %-5level %logger{20} - %msg%n&quot;/&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &amp;lt;!-- ── 开发环境：控制台彩色输出 ─────────────────────────── --&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;springProfile name=&quot;default,dev&quot;&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;appender name=&quot;CONSOLE&quot; class=&quot;ch.qos.logback.core.ConsoleAppender&quot;&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;encoder class=&quot;ch.qos.logback.classic.encoder.PatternLayoutEncoder&quot;&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;pattern&amp;gt;%clr(%d{HH:mm:ss}){faint} %clr([%thread]){magenta} %clr([%X{traceId}]){cyan} %clr(%-5level) %clr(%logger{20}){cyan} - %msg%n&amp;lt;/pattern&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;charset&amp;gt;UTF-8&amp;lt;/charset&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;/encoder&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;/appender&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &amp;lt;root level=&quot;INFO&quot;&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;appender-ref ref=&quot;CONSOLE&quot;/&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;/root&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;/springProfile&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>    &amp;lt;!-- ── 生产环境：JSON 格式滚动文件输出 ───────────────────── --&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;springProfile name=&quot;prod&quot;&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;appender name=&quot;FILE&quot; class=&quot;ch.qos.logback.core.rolling.RollingFileAppender&quot;&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;file&amp;gt;\${LOG_DIR}/\${APP_NAME}.log&amp;lt;/file&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;rollingPolicy class=&quot;ch.qos.logback.core.rolling.TimeBasedRollingPolicy&quot;&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;fileNamePattern&amp;gt;\${LOG_DIR}/\${APP_NAME}.%d{yyyy-MM-dd}.log&amp;lt;/fileNamePattern&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;maxHistory&amp;gt;30&amp;lt;/maxHistory&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;totalSizeCap&amp;gt;5GB&amp;lt;/totalSizeCap&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;/rollingPolicy&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;encoder class=&quot;ch.qos.logback.classic.encoder.PatternLayoutEncoder&quot;&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;pattern&amp;gt;{&quot;time&quot;:&quot;%d{yyyy-MM-dd HH:mm:ss.SSS}&quot;,&quot;thread&quot;:&quot;%thread&quot;,&quot;traceId&quot;:&quot;%X{traceId}&quot;,&quot;level&quot;:&quot;%-5level&quot;,&quot;logger&quot;:&quot;%logger{36}&quot;,&quot;message&quot;:&quot;%replace(%msg){&#39;\\&quot;&#39;,&#39;\\\\&quot;&#39;}&quot;}%n&amp;lt;/pattern&amp;gt;</span></span>
<span class="line"><span>                &amp;lt;charset&amp;gt;UTF-8&amp;lt;/charset&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;/encoder&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;/appender&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &amp;lt;appender name=&quot;FILE_ASYNC&quot; class=&quot;ch.qos.logback.classic.AsyncAppender&quot;&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;discardingThreshold&amp;gt;0&amp;lt;/discardingThreshold&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;queueSize&amp;gt;512&amp;lt;/queueSize&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;appender-ref ref=&quot;FILE&quot;/&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;/appender&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>        &amp;lt;root level=&quot;INFO&quot;&amp;gt;</span></span>
<span class="line"><span>            &amp;lt;appender-ref ref=&quot;FILE_ASYNC&quot;/&amp;gt;</span></span>
<span class="line"><span>        &amp;lt;/root&amp;gt;</span></span>
<span class="line"><span>    &amp;lt;/springProfile&amp;gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>&amp;lt;/configuration&amp;gt;</span></span></code></pre></div><p>traceId的价值：一个对话请求从Controller进来，经过Service、调LLM、写数据库，可能产生十几条日志。一个ID串起整条链路，排查时不用大海捞针。</p><h2 id="最终验收" tabindex="-1">最终验收 <a class="header-anchor" href="#最终验收" aria-label="Permalink to &quot;最终验收&quot;">​</a></h2><p>三档全部搭完，回过头做一个整体检查：</p><ul><li><p>启动项目，确认日志格式正确（有traceId、有线程名）。</p></li><li><p>跑一遍DemoItem的CRUD，确认请求日志过滤器在记录每个请求的method、path、耗时。</p></li><li><p>检查日志里线程名是否有 <code>llm-</code> 和 <code>async-</code> 前缀的线程池就绪。</p></li></ul><p>全部通过，Hify后端基础组件全部就绪。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>这节课我们把Hify后端的全部基础组件搭完了。</p><ul><li><p>第一档（跑起来）：建表DDL、MapperScan扫描路径、LLM / 异步线程池。</p></li><li><p>第二档（能写业务）：BaseEntity、分页封装、入参校验、时间序列化、Spring Cache、CRUD标准流程。</p></li><li><p>第三档（健壮性）： HTTP 客户端（普通 + SSE）、熔断器（每个Provider独立）+ 重试、结构化日志 + 请求追踪。</p></li></ul><p>最重要的方法论是咨询模式。在你还没完全想清楚的时候，先让Claude Code帮你梳理全景，你做判断和取舍，再进入执行。多了一个前置思考环节，但能帮你发现遗漏。后面每次进入新阶段都可以用。</p><p>这一讲内容很多，我想多说一句， <strong>为什么要花这么大篇幅讲基础组件</strong>。</p><p>这门课教的不只是Claude Code的使用。我还想让你知道，一个标准项目的基础组件应该长什么样，包括线程池隔离、熔断重试、Cache-Aside、traceId串联、入参校验链路、统一时间序列化，这些东西不是课本上的概念，是每个生产级项目都要有的底层能力。很多工程师工作三五年，做的项目里这些东西是别人搭好的，自己从来没从零搭过，知道名字但说不清为什么要这么做。</p><p>这节课看完，你不只是用Claude Code搭好了Hify的基础组件，你还积累了一份可复用的基础组件清单，掌握了每个组件的设计理由。以后你开新项目，不管用不用Claude Code，这套东西基本照搬就行。三档优先级、每个组件解决什么问题、参数为什么这么设，你都心里有数。这才是真正的积累，不是只会问AI问题，而是自己也有经验、有判断。</p><p>下一讲进入前端。程序员一般没有设计师的审美，没关系，让Claude Code来。我们会让它帮我们做UI设计、定色调、优化布局，把灰蒙蒙的空壳变成有品牌感的界面，同时把前端的基础组件封装好。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>试一下咨询模式。打开Claude Code，描述你正在做的一个项目，然后问它：“在开始写业务代码之前，我应该准备哪些基础组件？”看看它的建议里有没有你没想到的，并把它的建议和你的判断（哪些采纳、哪些不需要、为什么）分享在留言区。</p><p>期待你与我交流。如果今天的课程让你有所收获，也欢迎转发给有需要的朋友，邀请他来一起学习，我们下节课再见！</p>`,113)])])}const h=s(t,[["render",l]]);export{g as __pageData,h as default};
